const sheets = $json.sheets || [];
const s = sheets.find(x => x.properties.title === 'Anna Call Agenda');
if (!s) return [{json:{requests:[]}}];
const sid = s.properties.sheetId;
const requests = [];

requests.push({updateSheetProperties:{properties:{sheetId:sid,gridProperties:{frozenRowCount:1,frozenColumnCount:1}},fields:'gridProperties(frozenRowCount,frozenColumnCount)'}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:{red:0.12,green:0.16,blue:0.22},horizontalAlignment:'LEFT',verticalAlignment:'MIDDLE',wrapStrategy:'WRAP',textFormat:{foregroundColor:{red:1,green:1,blue:1},bold:true,fontSize:11}}},fields:'userEnteredFormat(backgroundColor,horizontalAlignment,verticalAlignment,wrapStrategy,textFormat)'}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:100},cell:{userEnteredFormat:{verticalAlignment:'TOP',wrapStrategy:'WRAP',textFormat:{fontSize:10}}},fields:'userEnteredFormat(verticalAlignment,wrapStrategy,textFormat)'}});

[150,230,430,430,300].forEach((w,i) => {
  requests.push({updateDimensionProperties:{range:{sheetId:sid,dimension:'COLUMNS',startIndex:i,endIndex:i+1},properties:{pixelSize:w},fields:'pixelSize'}});
});

// Topic column bold
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:100,startColumnIndex:1,endColumnIndex:2},cell:{userEnteredFormat:{textFormat:{bold:true,fontSize:10}}},fields:'userEnteredFormat.textFormat'}});

// Answer column highlighted as the live fill-in
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:100,startColumnIndex:4,endColumnIndex:5},cell:{userEnteredFormat:{backgroundColor:{red:1,green:0.98,blue:0.9}}},fields:'userEnteredFormat.backgroundColor'}});

const secRule = (txt,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:100,startColumnIndex:0,endColumnIndex:1}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:txt}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(secRule('A. DECIDE',{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));
requests.push(secRule('B. MUST ASK',{red:1,green:0.87,blue:0.87},{red:0.6,green:0.11,blue:0.11}));
requests.push(secRule('C. IF TIME',{red:0.93,green:0.93,blue:0.93},{red:0.35,green:0.35,blue:0.35}));

// Put it right after Dashboard
requests.push({updateSheetProperties:{properties:{sheetId:sid,index:1},fields:'index'}});

return [{json:{requests}}];
